update content_bodies set title = '❝奇跡の清流❞ 仁淀川の四季(short version)', description = '“奇跡の清流”と呼ばれる仁淀川は、西日本最高峰・石鎚山から太平洋へと流れる一級河川です。
日本一の水質の川とも言われ、その美しい水の色は仁淀ブルーと呼ばれます。
絶景が楽しめる渓谷や、神秘的な森、山里に生きる人々の営みなど、日本の原風景が広がるエリアです。

この動画はショートバージョンです。
ロングバージョンはこちらからご覧になれます。
https://youtu.be/XgiEiTFiA7I

