update content_bodies set title = '❝Miraculous Clear Stream❞ The Four Seasons of Niyodo River (short version)', description = 'The Niyodo River, known as the "Miraculous Clear Stream," is a first-class river flowing from the highest peak in western Japan, Mount Ishizuchi, to the Pacific Ocean.
It is said to have the best water quality in Japan, and its beautiful water color is referred to as Niyodo Blue.
This area features breathtaking gorges, mystical forests, and the lives of people living in the mountain villages, showcasing Japan''s original landscapes.

This video is a short version.
You can watch the long version here:
https://youtu.be/XgiEiTFiA7I

