update content_bodies set title = '【夏篇】下北ゆかい村 PR動画（青森県風間浦村）', description = '下北ゆかい村公式HP
http://www.yukaimura.com/

幾百年ものあいだ湯治場として親しまれてきた下風呂温泉。津軽海峡を望む本州の北端をめぐる旅情。硫黄のにおいに包まれながら湯の街を歩き、海の幸に舌鼓を打つ。「湯」と「海」で、身も心も解きほぐす「ゆかい村」。また食べたくなる新鮮な海の幸、また会いたくなる温かな人、また行きたくなる心のふるさと。

そんな「ゆかい」の村、風間浦村があなたを待っています。' where id = 'wyHuzCCVMc9kFL2QXBx29';
update content_bodies set title = '[Summer Edition] Shimokita Yukai Village PR Video (Kazamaura, Aomori Prefecture)', description = 'Official website of Shimokita Yukai Village
http://www.yukaimura.com/

For hundreds of years, Shimoburo Onsen has been cherished as a hot spring resort. A journey around the northern tip of Honshu, overlooking the Tsugaru Strait. Walking through the hot spring town enveloped in the scent of sulfur, indulging in the flavors of the sea. A ''yukai village'' that relaxes both body and mind with ''hot springs'' and ''the sea.'' Fresh seafood that makes you want to eat again, warm people you want to meet again, a heartfelt hometown you want to visit again.

Such a ''yukai'' village, Kazamaura Village, is waiting for you.' where id = 'i4H3abqG_y6CrBoc9-Mot';
update content_bodies set title = '【鳥羽水族館🐠飼育係「森滝さん」イチ推しの「へんな生きもの」に会いに行こう🪼！】', description = '今年、開館70週年を迎えた鳥羽水族館。

日本で唯一飼育されているラッコやジュゴン、アシカやセイウチのショーが大人気✨️！でも、鳥羽水族館の魅力はそれだけではありません🙅

実は…
飼育種類数「日本一」を誇る水族館なんです🦭🐧🌊

飼育係の森滝さんに、数あるエリアの中から、最もディープな「へんな生きもの研究所」を案内いただき、鳥羽水族館の奥深い世界をのぞいてみましょう！

#鳥羽水族館 #へんな生きもの研究所 #観光三重 #kankomie' where id = 'kgUYasXQl24tHV4leIf9f';
update content_bodies set title = 'Let''s Go Meet the ''Weird Creatures'' Recommended by Toba Aquarium''s Caretaker, Mr. Moritaki! 🪼', description = 'This year marks the 70th anniversary of Toba Aquarium.

The shows featuring the only sea otters, dugongs, sea lions, and walruses in Japan are extremely popular! ✨️ But the charm of Toba Aquarium doesn''t stop there. 🙅

In fact...
It''s an aquarium that boasts the highest number of species in Japan! 🦭🐧🌊

Let''s have Mr. Moritaki, the caretaker, guide us through the most profound area, the ''Weird Creatures Research Institute,'' and take a peek into the deep world of Toba Aquarium!

#TobaAquarium #WeirdCreaturesResearchInstitute #TourismMie #kankomie' where id = 'a_yxasqlEsQunDk0N8TRv';
update content_bodies set title = '【魅惑のお花リレー🌼この春行きたいNo.1スポットをご紹介✨】', description = '行ってみたいと思ったら「🌷」、
今年はもう見たという人は「👍」と
コメント欄で教えてください！

今回は魅惑のお花リレー、
春行きたいNo.1を紹介しました🦋

2月ごろの梅に始まり、桜、
チューリップ、ネモフィラ…と
春のお花リレーが続くなばなの里。

4月5日現在、チューリップが
見ごろの最盛期を迎えていました！

今なら満開のソメイヨシノとの
競演も楽しめますよ！

チューリップの見頃は4月中旬ごろまで✨
今だけの絶景をぜひお見逃しなく‼︎

また、次のお花リレー走者、
ネモフィラの開花も
チューリップの隙間から
少しずつ始まってきています！

色とりどりのチューリップ畑が
次は一面ネモフィラブルーに…
幻想的な変化もどうぞお楽しみに✨

・・・・・・・・・・・・・・・・

なばなの里「チューリップまつり」

