update content_bodies set title = '三多気の桜【ドローン撮影】(津市)｜観光三重｜三重県の観光・旅行情報', description = '「日本さくら名所100選」に選ばれている津市美杉町の三多気の桜並木をドローンで撮影いたしました。古木が多く歴史を感じさせるヤマザクラ500本余りの並木道が、伊勢本街道から真福院までの参道に1.5km続きます。まるで桜のトンネルをくぐるかのようです。' where id = 'fQfhq6ABoMjEJoxIphUVu';
update content_bodies set title = 'Santake Cherry Blossoms [Drone Photography] (Tsu City) | Tourism Mie | Mie Prefecture Travel Information', description = 'We captured the cherry blossom avenue of Santake in Misugi Town, Tsu City, which has been selected as one of the ''100 Famous Cherry Blossom Spots in Japan,'' using a drone. The avenue, lined with over 500 ancient Yamazakura trees that evoke a sense of history, stretches 1.5 km from Ise Honkaido to Shinpukuin, creating a tunnel of cherry blossoms.' where id = 'q8Y30O285ZU6p_x_qyKif';
update content_bodies set title = 'みえのイマココ旅　「自然」×「食」vol.2　編　JAPAN MIE／nature×eat　vol.2', description = '■みえのイマココ旅とは？ 『三重の「イマしかない」「ココしかない」』体験を楽しみに三重を訪れよう』がコンセプト。「自然」「歴史・文化」「伝統」「ものづくり」「食」「ナイト＆モーニング」「サスティナブル」をテーマに、これまでにない新しい旅のカタチをご提案します。

■みえのイマココ旅　特設サイト「自然」「歴史・文化」「伝統」「ものづくり」「食」「ナイト＆モーニング」「サスティナブル」をテーマとした50以上の体験プランを紹介しており、各プランの予約ができます。 https://www.kankomie.or.jp/special/imakoko/ 

■「自然」×「食」　vol.2について 大紀町・大内山川での鮎を友釣りして食べるツアー、紀北町で生まれ育つ幻の牡蠣ツアーなど、三重県が誇る「自然と食」を堪能できる特別な体験を紹介しています。 

