[If you don''t stop by, you''ll be missing out!! Eat around Ise Jingu - exquisite Japanese sweets]

I want to stop by when I go to Ise Jingu!
Operated by a tea shop that has been around since the Meiji era.
A shop where you can enjoy Ise tea sweets [Kinoshita Chaen]

Popular menu is [Ise Shiratama Mochi]
Shiratama balls are boiled after your order is placed and are piping hot and chewy!
The generous amount of matcha soybean powder has just the right amount of sweetness and bitterness.
Deliciousness that you can eat with ease😋

[Ise Matcha Latte] is an authentic dish made by brewing Ise Matcha for each order✨
You can fully enjoy the original flavor and aroma of matcha.

Check here for more details👇
https://www.kinoshitachaen.com

📸Kinoshita Tea Garden Naiku-mae branch
📍18 Ujiimazaikecho, Ise City, Mie Prefecture
