[I want to see it!! I want to eat it! Luxury rich sweets with a thickness of 1 mm]

We have a rich menu using local ingredients!
Yokkaichi Factory Cafe is a popular cafe where you can enjoy Mont Blanc squeezed right in front of your eyes.

A delicate and fluffy marron cream with a thickness of 1 mm is squeezed out in front of your eyes🌰
The secret ingredient is rum, so it has a mature taste.
Inside the cream is vanilla ice cream, custard, and crunchy crumble!
Furthermore, as a finishing touch, generously sprinkle with shaved chestnuts,
The restaurant''s specialty is that you can enjoy a variety of textures✨

There are two flavors: marron and kabusecha!
Limited time sale from October to March 😊

Check here for more details👇
http://www.suwakouen-kouryukan.com

📸Suwa Park
📍5, Suwa Sakae-cho, Yokkaichi City, Mie Prefecture
