update content_bodies set title = 'Directly Operated Restaurant of ''Matoya Oysters'' 🦪', description = 'A hot topic in the media! Directly operated restaurant of ''Matoya Oysters'' 🦪✨

The first brand of Mie, ''Matoya Oysters'',
has gained attention both domestically and internationally for its deliciousness and high quality that is safe to eat raw.

In 2022, ''Matoya Oyster Terrace'' opened right next to Sato Aquaculture,
becoming a hot topic for offering fresh oysters from its own farm all year round. 😲‼

We will introduce a variety of dishes, including the winter favorite ''Iron Pot Steamed Oysters''
and the ''Oyster Full Course'' featuring 8 dishes using oysters. 💞✨

