update content_bodies set title = 'The ''Blue Cave'' in Mie Prefecture ✨', description = 'A sightseeing boat 🚢✨ that offers views of the ''Blue Cave'' and breathtaking scenery in Mie Prefecture.

The sightseeing boat will take you on a tour of the scenic spots in the following order:
〈Oni no K城 → Jofuku no Miya → Blue Cave (Gama no Kuchi) → Tate no Saki → Umikongo〉

Except for the ''Blue Cave'', all spots are accessible from land, but the view from the sea is different and has a special feel to it 🤭💞

📍Tate no Saki Sightseeing Boat
Inquiry ▶ 0597-89-2229 (Kumano City Tourism Association)
Departure Point ▶ Matsuzaki Port (Check the map on the official website)
Departure Times ▶ 10:00～ / 12:00～ / 14:00～
*The ride lasts about 1 hour and 10 minutes.
*There is no 14:00 service on Sundays.
Closed Days ▶ New Year’s holidays
Parking ▶ Available (Free)
Price ▶ 4,500 yen per person for 2 passengers
*Single passenger boarding is not allowed.

