update content_bodies set title = 'A picture board made of colorful shells?! A photogenic scenic view✨', description = 'A picture board made of colorful shells?! A breathtaking view that can only be seen here✨

Colorful shell picture boards are available for sale,
and you can write your wishes on the shells and dedicate them.
The sight of the colorful shells lined up is very beautiful,
and a photogenic scene unfolds💞

Next to the observation deck, the ''Tsubasu no Kane'' is said to grant wishes when rung.

The sunset view, selected as one of the ''100 Best Sunsets in Japan,'' was breathtakingly beautiful on a clear day.
*Unfortunately, the weather was not great on the day of the shoot...😢

📍Isofue Cape Observation Deck
