update content_bodies set title = '【三重県】入園料無料で、たくさんの動物とふれあえる動物園をご紹介します✨🐷🐐', description = '入園料無料で、たくさんの動物とふれあえる
動物園をご紹介します✨🐷🐐

ここの園長さんの本業は、塗装屋「タケガワ塗装」のオーナー。
行き場のないリクガメやマイクロブタなどを保護したことがきっかけで、
「いっそ動物園にしよう！」と開園を思い立ったとのこと。

「たくさんの人に命の温もりを感じてもらいたい」
との思いから、誰もが気軽に遊びに来られるように無料開放しています。

ロバやポニー、ヤギ、ウサギなどたくさんの動物と
距離感ゼロでふれあえるスポットにぜひ遊びにいってみて🎶

