update content_bodies set title = '[Mie Prefecture] Introducing a zoo where you can interact with many animals for free! ✨🐷🐐', description = 'Introducing a zoo where you can interact with many animals for free! ✨🐷🐐

The owner of this zoo is the head of a painting company called ''Takegawa Painting.'' 
After rescuing tortoises and micro pigs that had nowhere to go, he thought, ''Why not make it a zoo!'' and decided to open it.

With the desire to let many people feel the warmth of life, it is open for free so that anyone can easily come and visit.

Please come and enjoy a spot where you can interact with many animals like donkeys, ponies, goats, and rabbits at zero distance! 🎶

📍Takegawa Interaction Zoo
