update content_bodies set title = '[Mie Prefecture] Like a ''Pink Carpet'' #kankomie #TourismMie #ShimaCityTourismFarm', description = 'On a gentle slope, it''s like a ''pink carpet'' 💞

The park opens in time for the blooming of cosmos and nemophila 🌻
You can enjoy a variety of colorful flowers depending on the season ✨

This year, you can enjoy the cosmos field until Sunday, November 19th!
There are also photo spots where you can take cute pictures with the cosmos!

You can also see the round and adorable ''Kokia''! 🎉
In November, you might see the Kokia turning bright red…?

*The photo was taken on October 18th.

*Even during the opening period, the opening duration may be shortened depending on the blooming status, so please check the blooming and opening status on Instagram before visiting.

