update content_bodies set title = '[Mie Prefecture] Japan''s Largest ''Flower Theme Park'' Cosmos Festival 🌸 #kankomie #TourismMie #NabanaNoSato', description = 'Attention to Japan''s largest ''Flower Theme Park'' Cosmos Festival❣

In the largest flower field in Japan, seasonal flowers are said to bloom beautifully.
From late September to early November each year, you can enjoy 1.5 million cosmos flowers✨

The ''Begonia Garden'' that can be enjoyed year-round is also recommended!
You will be thrilled by the space that feels like stepping into a painting.

Don''t miss the cosmos fields that are in full bloom right now, hurry up! 🏃💨💨

*The photo was taken on October 18.

*Even during the opening period, the opening duration may be shortened depending on the blooming conditions, so please check the blooming status and opening status before your visit.

📍Shima City Tourist Farm
