update content_bodies set title = '六華苑（旧二代諸戸清六邸）【ドローン撮影】(桑名市)｜観光三重｜三重県の観光・旅行情報', description = '桑名の大実業家だった二代諸戸清六の新居として、大正２年（1913年）に完成した六華苑。4層の塔屋を持つ特徴的な洋館は、あの有名な鹿鳴館を手掛けたイギリス人の建築家ジョサイア・コンドルの設計によるもの。洋館に連結して建つ和館、蔵、池泉回遊式庭園など、創建時の姿がほぼそのまま残されており、洋館と和館は国の重要文化財に指定されています。' where id = 'nWYLX1_hV60fD-_Te5_Gn';
update content_bodies set title = 'Rikkaen (Former Residence of the Second Generation Moroto Seiroku) [Drone Photography] (Kuwana City) | Tourism Mie | Mie Prefecture Travel Information', description = 'Rikkaen was completed in 1913 as the new residence of the prominent businessman Moroto Seiroku, the second generation. The distinctive Western-style building with a four-story tower was designed by the British architect Josiah Conder, who also worked on the famous Rokumeikan. The Japanese-style building, storehouse, and pond-style garden connected to the Western-style building have largely retained their original appearance, and both the Western and Japanese buildings are designated as Important Cultural Properties of the country.' where id = 'dDREDea0eepyubSc_EE3V';
