update content_bodies set title = 'Opened at the end of May 2023! Introducing the charm of ''Tsuboyaki Imo Imoan''♪', description = 'The interior feels like... a classroom!? With blackboards, desks, and even school bags! 

This is a specialty store for tsuboyaki sweet potatoes that opened at the end of May this year 🍠

Inspired by the traditional ''imo'', the interior is designed to evoke nostalgic feelings for everyone, 
just like an elementary school 🏫🎒. The completely recreated space is fun and somehow calming.

The signature menu item, ''Tsuboyaki Imo'', is an unbeatable value at 380 yen 🥰. 
In summer, the fluffy melting ''Yaki Imo Milk Ice'' is highly recommended ✨

-------------------------------------------

