update content_bodies set title = '七里御浜【ドローン撮影】(熊野市)｜観光三重｜三重県の観光・旅行情報里御浜', description = '世界遺産熊野古道「浜街道」としても知られる七里御浜をドローンで空撮しました！熊野市から紀宝町に至る約22Ｋｍ続く日本で一番長い砂礫海岸。これまでに「日本の渚百選」や「21世紀に残したい自然百選」など全国の景勝地と並んで選ばれています。荒々しい黒潮をおおらかに受けとめるこの浜には、熊野灘の荒波に磨かれた丸い小石が敷き詰められた美しい海浜です。' where id = '5B_t-K7RIlb0CKoJxtfA5';
update content_bodies set title = 'Shichiri Mihama [Drone Photography] (Kumano City) | Tourism Mie | Mie Prefecture Travel Information', description = 'We captured Shichiri Mihama, also known as the World Heritage Kumano Kodo ''Hama Kaido'', with a drone! This is the longest gravel beach in Japan, stretching approximately 22 km from Kumano City to Kiho Town. It has been selected alongside other scenic spots nationwide, such as ''Japan''s Top 100 Beaches'' and ''Top 100 Natural Sites to Preserve for the 21st Century''. This beautiful beach, which gracefully embraces the rough Kuroshio Current, is adorned with round pebbles polished by the rough waves of Kumano-nada.' where id = 'PO8zSln85JX3aXaeuTxWR';
update content_bodies set title = '伊勢志摩リゾートステイ', description = '複雑に入り組んだ半島が織りなすリアス海岸美や大小の島々が作り出す”自然”や、
