update content_bodies set title = 'みえのイマココ旅　「歴史文化×食」編　JAPAN MIE／Historical experiences with food', description = '■みえのイマココ旅とは？
『三重の「イマしかない」「ココしかない」』体験を楽しみに三重を訪れよう』がコンセプト。「歴史文化」「自然」「食」「ナイト＆モーニング」「サスティナブル」をテーマに、これまでにない新しい旅のカタチをご提案します。

■みえのイマココ旅　特設サイト
「歴史文化」「自然」「食」「ナイト＆モーニング」「サスティナブル」をテーマとした４６の体験プランを紹介しており、各プランの予約ができます。
https://www.kankomie.or.jp/special/imakoko/

■「歴史文化」×「食」について
国宝・高田本山専修寺でいただく和会席、松阪豪商の邸宅であった射和文庫での茶事など、三重県が誇る「歴史文化」と「食」を堪能できる特別な体験を紹介しています。

