update content_bodies set title = 'Mie no Imakoko Travel: "History and Culture × Food" Edition JAPAN MIE / Historical experiences with food', description = '■ What is Mie no Imakoko Travel?
The concept is to enjoy experiences in Mie that are "only available now" and "only here." We propose a new form of travel that has never been seen before, themed around "History and Culture," "Nature," "Food," "Night & Morning," and "Sustainable."

■ Mie no Imakoko Travel Special Site
We introduce 46 experience plans themed around "History and Culture," "Nature," "Food," "Night & Morning," and "Sustainable," where you can make reservations for each plan.
https://www.kankomie.or.jp/special/imakoko/

■ About "History and Culture" × "Food"
We introduce special experiences where you can enjoy Mie Prefecture''s proud "History and Culture" and "Food," such as a Japanese kaiseki meal at the National Treasure Takada Honzan Senshuji and a tea ceremony at the former residence of a Matsusaka merchant, Iwa Bunko.

