update content_bodies set title = '～梅～　三重梅めぐり　鈴鹿の森庭園', description = '三重県は、実は梅の名所。日本最古と思われる呉服しだれ「天の龍」をはじめ見事なしだれ梅の名木が約200本ある「鈴鹿の森庭園」は、日本伝統園芸文化のひとつである「仕立て技術」の存続と普及を目的として、研究栽培を行っています。梅の見頃に合わせた時期のみ一般公開しており、夜間ライトアップも行っています。

