update content_bodies set title = 'Ume - Mie Ume Tour - Suzuka no Mori Garden', description = 'Mie Prefecture is actually a famous place for ume (plum blossoms). The ''Suzuka no Mori Garden'', which has about 200 magnificent weeping ume trees, including the ''Amanoryu'', believed to be the oldest in Japan, conducts research cultivation aimed at the preservation and dissemination of ''shitate technology'', one of Japan''s traditional horticultural cultures. It is open to the public only during the peak viewing season of the ume blossoms, and there is also a night illumination event.

*Drone footage has been filmed with special permission.

