update content_bodies set title = '透明度抜群！御座白浜海水浴場でシーカヤック【伊勢志摩グランピング】LUXUNA伊勢志摩　マリンアクティビティ', description = 'カヤックはカヤックでも、「クリアカヤック」はご存知でしょうか？ボディーもオールもすべて透明なカヤックなんです

これが、三重県No.1の透明度を誇るとも言われる御座白浜海水浴場の透き通る海と相性バツグン！透き通ったカヤック越しに、水中の様子をじっくり楽しむことができます。魚が真下を泳いでいくことも！

【体験できる施設】「ラグナ伊勢志摩LUXUNA」
※2021年7月に伊勢志摩にオープンしたばかりのグランピング施設で、「LUXURY(贅沢)」と「NATURAL(自然) 」をかけあわせて「LUXUNA(ラグナ)」という名前が付けられています。ラグナ伊勢志摩は、グランピング感あふれる快適な施設と、豪華な食事、そして自然を堪能できる仕掛けやアクティビティがエリアいっぱいに広がっています

【料金】クリアカヤックはガイド付きプランのみで90分税込7,500円(／お一人様)。
通常のカラーカヤックは90分税込3,300円(／お一人様)、ガイド付きプランだと90分税込5,500円(／お一人様)

