update content_bodies set title = 'Outstanding Transparency! Sea Kayaking at Goza Shirahama Beach 【Ise-Shima Glamping】 LUXUNA Ise-Shima Marine Activities', description = 'Did you know about ''clear kayaks''? They are completely transparent, both the body and the paddles.

This pairs perfectly with the crystal-clear waters of Goza Shirahama Beach, said to boast the highest transparency in Mie Prefecture! You can thoroughly enjoy the underwater scenery through the transparent kayak. Fish can swim right beneath you!

【Experience Facility】 ''LAGUNA Ise-Shima LUXUNA''
*This glamping facility just opened in July 2021 in Ise-Shima, combining ''LUXURY'' and ''NATURAL'' to create the name ''LUXUNA''. LAGUNA Ise-Shima offers comfortable facilities full of glamping vibes, luxurious meals, and a variety of experiences and activities to enjoy nature throughout the area.

【Pricing】 Clear kayaks are available only with a guided plan for 90 minutes at 7,500 yen (including tax) per person.
