update content_bodies set title = '高田本山 専修寺 (三重県津市)', description = '専修寺は、全国に600余ヶ寺ある真宗高田派の本山寺院です。開山親鸞聖人のみ教えをまっすぐに受け継ぐ寺院で、境内の御廟にはご遺骨をお守りしています。三重県津市一身田町に位置し、親しみを込め高田本山と呼ばれています。
2017年11月三重県初の国宝建造物に指定された、如来堂・御影堂（みえいどう）に加え、国宝の法宝物や国指定の重要文化財を数多く抱えています。境内ではお浄土に咲くとされる蓮の花を、35種類100鉢以上楽しむことができます。また毎年１月９日から１６日まで、真宗最大の法会“報恩講”を行っています。

※令和2年度文化財多言語解説整備事業の補助を受けて作成した動画です。' where id = '18pdbamYDJrhSrgXjr7cX';
update content_bodies set title = 'Takada Honsan Senshuji (Tsu City, Mie Prefecture)', description = 'Senshuji is the head temple of the Shinshu Takada sect, with over 600 temples nationwide. It is a temple that directly inherits the teachings of the founder, Shinran Shonin, and the remains are enshrined in the mausoleum on the temple grounds. Located in Ichinada Town, Tsu City, Mie Prefecture, it is affectionately called Takada Honsan.
In November 2017, it was designated as the first national treasure building in Mie Prefecture, along with the Nyorai-do and Mieido, and it houses numerous national treasures and important cultural properties designated by the country. On the temple grounds, you can enjoy over 100 pots of lotus flowers, said to bloom in the Pure Land, with 35 different varieties. Additionally, the largest Shinshu ceremony, the ' where id = 'AjfzUeZRb8Gki7w2_qXfG';
