update content_bodies set title = 'クライミングジム キャニオン　岩場体験会【ドローン撮影】', description = '東京五輪の追加種目にも採用されたことから最近注目されているクライミング。朝日町にあるクライミングジム キャニオンでは、インドアでのボルダリングはもちろん、岩場スポットへ出かけての岩場体験など、アウトドアでのクライミングの楽しさも教えてくれます。今回は人生初の岩場体験に挑戦してきました！' where id = 'aiEhfmntmNfB-7I9OAQ_7';
