Mie Prefecture has collaborated with ''Discover Japan'' to introduce various ''VIBRATIONS'' emitted by Mie, based on the concept of ''FEEL VIBRATIONS''. Travelers will experience the ''mystical vibrations'' of Ise Jingu and Kumano Kodo, the ''breath'' of history rooted in Takada Honganji and Iga, and the ''heartbeat'' of the sea felt in Ago Bay. After feeling Mie''s ''VIBRATIONS'' in the video, participate in the ''Mie Travel Premium Campaign'' by ''staying in Mie'' and ''answering'' to win luxurious prizes!
