update content_bodies set title = 'Ugura Park Drone Footage (Minamiise Town, Mie Prefecture) | Kankou Mie | Mie Prefecture Tourism and Travel Information', description = 'Enjoy the beautiful views of the unique ria coastline of Ise-Shima National Park.
