update content_bodies set title = '三重県大台町の紅葉ドローン映像｜観光三重｜三重県の観光・旅行情報', description = '日本三大渓谷の一つ「大杉谷」がある三重県大台町。
自然豊かな大台町には、美しい紅葉スポットがたくさんあります。
ドローンで撮影した紅葉映像をお楽しみくだです。
（動画提供：大台町地域おこし協力隊　井坂 治 氏）

